# Вопрос о выборе внутри уже показанного набора: «какой из них дешевле»,
# «который лучше», «что из этих надёжнее».
SHOWN_SET_COMPARISON_RE = re.compile(
    r"(?:как(?:ой|ая|ое|ие)|котор(?:ый|ая|ое|ые)|что)\s+"
    r"(?:из\s+(?:них|этих|перечисленных|показанных|предложенных|вариантов)\s+)?"
    r"(?:лучше|дешевл\w*|дороже|надежнее|предпочтительнее)"
    r"|\bиз\s+(?:них|этих|показанных|предложенных|перечисленных)\b"
    r"|\bсреди\s+(?:них|этих)\b"
)


class ChatOrchestrator:
    def __init__(
        self,
        settings: Settings | None = None,
        products: list[Product] | None = None,
        llm_client: OpenRouterClient | None = None,
        session_store: SessionStore | None = None,
    ) -> None:
        self.settings = settings or get_settings()
        self.feed_loader = FeedLoader(self.settings)
        self.llm_client = llm_client or OpenRouterClient(self.settings)
        self.sessions = session_store or build_session_store(
            self.settings.session_store_url,
            ttl_seconds=self.settings.session_ttl_seconds,
            lock_timeout_seconds=self.settings.session_lock_timeout_seconds,
        )
        # V2 normalizes the same mutable ``Product`` records that the legacy
        # path and the Passport Agent use.  Documentation-derived attributes
        # must be attached *before* either V2 snapshot is built: otherwise a
        # cold start can answer a direct passport fact but cannot use that same
        # verified rating while selecting cards.  ``reload_products`` already
        # has this order; keep construction consistent with reload.
        self.docs_attached = 0
        if products:
            self.docs_attached = load_docs_for_products(products, self._docs_dirs())
        self.intent_router = IntentRouterAgent(
            self.llm_client,
            catalog_brands=[
                product.brand
                for product in (products or [])
                if product.brand
            ],
        )
        self.engineering_interpreter = EngineeringInterpreterAgent(self.llm_client)
        self.pending_answer_resolver = PendingAnswerResolver(self.llm_client)
        self.turn_classifier = TurnClassifierAgent(self.llm_client)
        self.turn_planner = TurnPlanner()
        self.slot_filling = SlotFillingAgent()
        self.engineering_requirements = EngineeringRequirementsAgent(
            self.slot_filling
        )
        self.search_agent = DiagnosticFeedSearchAgent(products or [])
        self.semantic_interpreter = SemanticInterpreter(
            self.llm_client,
            model=(
                self.settings.semantic_shadow_model
                or self.settings.llm_model_strong
            ),
            catalog_products=products or (),
        )
        self.dialogue_controller_v2 = DialogueControllerV2(
            response_renderer=ResponseRendererV2(
                self.llm_client,
                model=self.settings.llm_model_strong,
            )
        )
        self.cutover_registry_v2 = load_registry(
            self.settings.dialogue_v2_migration_registry_path
        )
        self.commerce_capabilities_v2 = (
            build_capability_snapshot(get_business_facts())
            if self._stage4_shadow_enabled() or self._qa_v2_resources_enabled()
            else build_capability_snapshot()
        )
        self.catalog_snapshot_v2 = (
            build_catalog_snapshot(products or [])
            if (
                self._stage3_shadow_enabled()
                or self._stage5_shadow_enabled()
                or self._stage6_pipeline_enabled()
                or self._qa_v2_resources_enabled()
            )
            else ()
        )
        self.answer_source_snapshot_v2 = (
            build_answer_source_snapshot(
                products or [],
                self.catalog_snapshot_v2,
                capability_facts=build_verified_business_capability_facts(
                    get_business_facts()
                ),
            )
            if (
                self._stage5_shadow_enabled()
                or self._stage6_pipeline_enabled()
                or self._qa_v2_resources_enabled()
            )
            else None
        )
        self.ranking_agent = RankingAgent()
        self.card_agent = ProductCardAgent()
        self.guardrails = GuardrailsAgent()
        # Composer and consultant expose request-scoped diagnostic state
        # (history, draft, last products/LLM result).  A single shared instance
        # leaked that state when FastAPI handled different users concurrently.
        self._request_agents = local()
        self._catalog_load_lock = RLock()
        self._session_locks_guard = RLock()
        self._session_locks: dict[str, RLock] = {}
        self.handoff = HandoffAgent()
        self.products_loaded_from = "injected" if products is not None else "none"
        self.product_fact_evidence = ProductFactEvidenceService(
            self.settings,
            self.llm_client,
            self.search_agent.products,
            catalog_snapshot=self.catalog_snapshot_v2,
        )

    def _docs_dirs(self) -> list[Any]:
        return [self.settings.product_docs_dir, PROJECT_ROOT / "data"]

    def reload_products(self, refresh: bool = True) -> tuple[int, str]:
        with self._catalog_load_lock:
            products, source = self.feed_loader.load_products(refresh=refresh)
            self.docs_attached = load_docs_for_products(products, self._docs_dirs())
            self.search_agent.set_products(products)
            self.semantic_interpreter.set_catalog_products(products)
            self.product_fact_evidence.set_products(products)
            if (
                self._stage3_shadow_enabled()
                or self._stage5_shadow_enabled()
                or self._stage6_pipeline_enabled()
                or self._qa_v2_resources_enabled()
            ):
                self.catalog_snapshot_v2 = build_catalog_snapshot(products)
            self.product_fact_evidence.set_catalog_snapshot(
                self.catalog_snapshot_v2
            )
            if (
                self._stage5_shadow_enabled()
                or self._stage6_pipeline_enabled()
                or self._qa_v2_resources_enabled()
            ):
                self.answer_source_snapshot_v2 = build_answer_source_snapshot(
                    products,
                    self.catalog_snapshot_v2,
                    capability_facts=build_verified_business_capability_facts(
                        get_business_facts()
                    ),
                )
            self.intent_router.set_catalog_brands(
                [product.brand for product in products if product.brand]
            )
            self.products_loaded_from = source
            return len(products), source

    def _ensure_products_loaded(self) -> bool:
        """Load the cached catalogue once before catalogue-aware intent handling."""
        if self.search_agent.products:
            return True
        with self._catalog_load_lock:
            if self.search_agent.products:
                return True
            try:
                self.reload_products(refresh=False)
            except Exception as exc:
                logger.exception("Cannot load products for intent handling: %s", exc)
        return bool(self.search_agent.products)

    def _stage3_shadow_enabled(self) -> bool:
        return bool(
            self.settings.product_contracts_v2_shadow_enabled
            or self.settings.catalog_planner_v2_shadow_enabled
            or self.settings.solution_plan_v2_shadow_enabled
        )

    def _stage4_shadow_enabled(self) -> bool:
        return bool(
            self.settings.commerce_workflows_v2_shadow_enabled
            or self.settings.handoff_workflow_v2_shadow_enabled
            or self.settings.commerce_outbox_v2_shadow_enabled
        )

    def _stage5_shadow_enabled(self) -> bool:
        return bool(
            self.settings.answer_plan_v2_shadow_enabled
            or self.settings.response_renderer_v2_shadow_enabled
            or self.settings.response_grounding_v2_shadow_enabled
            or self.settings.progress_guard_v2_shadow_enabled
        )

    def _stage6_pipeline_enabled(self) -> bool:
        return bool(
            self.settings.dialogue_v2_routing_enabled
            and (
                self.settings.dialogue_v2_shadow_compare_enabled
                or self.settings.dialogue_v2_live_delivery_enabled
                or self.settings.dialogue_v2_internal_canary_enabled
                or self.settings.dialogue_v2_local_preview_enabled
            )
        )

    def _qa_v2_resources_enabled(self) -> bool:
        return bool(
            self.settings.dialogue_v2_qa_controls_enabled
            and self.settings.dialogue_v2_qa_control_token
        )

    def _stage6_live_attempt_enabled(
        self,
        qa_mode: DialogueQAMode | None = None,
    ) -> bool:
        if qa_mode in {DialogueQAMode.LEGACY, DialogueQAMode.SHADOW}:
            return False
        if qa_mode == DialogueQAMode.V2_PREVIEW:
            return bool(
                self._qa_v2_resources_enabled()
                and not self.settings.commerce_external_execution_enabled
                and not self.settings.dialogue_v2_force_legacy
            )
        return bool(
            self.settings.dialogue_v2_routing_enabled
            and self.settings.dialogue_v2_live_delivery_enabled
            and (
                (
                    self.settings.dialogue_v2_internal_canary_enabled
                    and self.settings.dialogue_v2_internal_canary_percent > 0
                )
                or self.settings.dialogue_v2_local_preview_enabled
            )
            and not self.settings.commerce_external_execution_enabled
            and not self.settings.dialogue_v2_force_legacy
        )

    @property
    def composer(self) -> ResponseComposerAgent:
        agent = getattr(self._request_agents, "composer", None)
        if agent is None:
            agent = ResponseComposerAgent(self.llm_client)
            self._request_agents.composer = agent
        return agent

    @property
    def consultant(self) -> ConsultantAgent:
        agent = getattr(self._request_agents, "consultant", None)
        if agent is None:
            agent = ConsultantAgent(
                self.llm_client,
                model=self.settings.llm_model_strong,
            )
            self._request_agents.consultant = agent
        return agent

    @staticmethod
    def _response_digest(response: ChatResponse) -> str:
        payload = response.model_dump(mode="json", exclude={"debug"})
        return hashlib.sha256(
            json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()

    @staticmethod
    def _idempotent_response(
        state: SessionState,
        client_turn_id: str | None,
    ) -> ChatResponse | None:
        if not client_turn_id:
            return None
        record = next(
            (
                item
                for item in reversed(state.idempotent_responses)
                if item.client_turn_id == client_turn_id
            ),
            None,
        )
        if record is None:
            return None
        return ChatResponse.model_validate(record.response_payload)

    def _record_idempotent_response(
        self,
        state: SessionState,
        client_turn_id: str | None,
        response: ChatResponse,
    ) -> None:
        if not client_turn_id:
            return
        if any(
            item.client_turn_id == client_turn_id
            for item in state.idempotent_responses
        ):
            return
        state.idempotent_responses = [
            *state.idempotent_responses,
            IdempotentResponseRecord(
                client_turn_id=client_turn_id,
                response_payload=response.model_dump(mode="json"),
                response_digest=self._response_digest(response),
                session_revision=state.session_revision,
            ),
        ][-20:]

    def _stage6_early_control(
        self,
        message: str,
        before_turn: SessionState,
    ) -> EarlyControlResult:
        """Reuse verified legacy guards on an isolated snapshot before V2 routing."""

        scratch = before_turn.model_copy(deep=True)
        checks = (
            (
                EarlyControlOutcome.SAFETY_RESPONSE,
                "water_heater_operational_safety",
                self._maybe_water_heater_operational_safety_answer,
            ),
            (
                EarlyControlOutcome.EMERGENCY_RESPONSE,
                "water_emergency",
                self._maybe_water_emergency_answer,
            ),
            (
                EarlyControlOutcome.SAFETY_RESPONSE,
                "gas_work_safety",
                self._maybe_gas_work_answer,
            ),
            (
                EarlyControlOutcome.SAFETY_RESPONSE,
                "gas_appliance_safety",
                self._maybe_gas_safety_answer,
            ),
            (
                EarlyControlOutcome.SAFETY_RESPONSE,
                "electrical_safety",
                self._maybe_electrical_safety_answer,
            ),
            (
                EarlyControlOutcome.BLOCKED,
                "customer_photo_capability_boundary",
                self._maybe_customer_photo_boundary,
            ),
        )
        for outcome, reason, checker in checks:
            if checker(message, scratch):
                return EarlyControlResult(
                    outcome=outcome,
                    reason_codes=(reason,),
                )
        if redact_pii_for_model(message) != message:
            return EarlyControlResult(
                outcome=EarlyControlOutcome.PII_CONTROL,
                reason_codes=("pii_present_route_to_legacy",),
            )
        return EarlyControlResult()

    def _run_stage6_v2_candidate(
        self,
        previous_state: DialogueStateV2,
        semantic: Any,
        turn_id: str,
        before_turn: SessionState,
    ) -> DialogueV2Outcome:
        return self.dialogue_controller_v2.run(
            previous_state,
            semantic,
            TurnMetadata(turn_id=turn_id),
            policy_enabled=True,
            product_contracts_enabled=True,
            catalog_planner_enabled=True,
            solution_plan_enabled=True,
            catalog_snapshot=self.catalog_snapshot_v2,
            # Read-only commerce planning is safe for the canary and lets a
            # mixed request keep delivery/quantity as a separate typed task.
            # External execution, handoff preparation and the outbox remain
            # disabled below, so this cannot create an order or send data.
            commerce_workflows_enabled=True,
            handoff_workflow_enabled=False,
            commerce_outbox_enabled=False,
            commerce_context=build_commerce_context_snapshot(
                before_turn,
                get_business_facts(),
            ),
            commerce_capabilities=build_capability_snapshot(
                get_business_facts()
            ),
            answer_plan_enabled=True,
            # The optional response LLM can only insert neutral transitions;
            # it cannot improve or change facts.  The deterministic renderer
            # is therefore the safer and cheaper live-canary default while
            # the same production model still performs semantic parsing.
            response_renderer_enabled=False,
            response_grounding_enabled=True,
            progress_guard_enabled=True,
            answer_source_snapshot=self.answer_source_snapshot_v2,
        )

    def _maybe_build_v2_product_fact_candidate(
        self,
        message: str,
        before_turn: SessionState,
        semantic: Any,
        outcome: DialogueV2Outcome,
        base_candidate: Any,
        *,
        session_id: str,
        turn_id: str,
    ) -> Any:
        """Give a typed direct question the shared product evidence service."""

        semantic_delta = getattr(semantic, "semantic_delta", None)
        current_actions = {
            getattr(item, "action", None)
            for item in getattr(semantic_delta, "action_candidates", ())
        }
        semantic_repairs = set(
            getattr(semantic_delta, "semantic_repairs", ())
        )
        action_plan = outcome.next_action_plan
        if (
            {"compare", "compatibility"}.intersection(current_actions)
            or (
                action_plan is not None
                and action_plan.primary.kind
                in {NextActionKind.COMPARE, NextActionKind.CHECK_COMPATIBILITY}
            )
        ):
            # Compare and Compatibility have their own multi-product evidence
            # boundaries. A fact detector must never turn either relationship
            # request into a one-product answer.
            return base_candidate
        # Explicit show commands own the turn before any pending
        # questionnaire fact.  Without this guard a stale decision question
        # can make ProductFactEvidenceService treat «Что есть?» as a request
        # for that old predicate and replace a valid Selection candidate.
        # ``select`` alone is intentionally insufficient: the semantic model
        # can emit it beside ``fact`` for an ordinal characteristic question.
        # Such a question must still reach ProductFactEvidenceService.
        if "show" in current_actions and semantic_repairs.intersection(
            {
                "explicit_show_selection_control_recovered",
                "generic_show_anchor_forced_continue",
            }
        ):
            return base_candidate

        action = action_plan.primary if action_plan is not None else None
        # Do not make product-fact delivery depend on the planner choosing one
        # particular action label.  The semantic LLM can legitimately describe
        # a question such as "Какая у первого монтажная длина?" as ``explain``;
        # the ordinary planner then emits WAIT_FOR_SEMANTIC_UNDERSTANDING.  The
        # bounded predicate detector below is stricter than that broad action
        # label: it only returns evidence for a supported direct product fact
        # (or a typed fail-closed refusal).  Safety has already passed through
        # the Stage 6 early-control gate before this method is called.
        semantic_fact_name = action.fact_name if action is not None else None
        understanding = getattr(semantic, "understanding", None)
        if (
            understanding is not None
            and action is not None
            and action.information_request_id is not None
        ):
            request = next(
                (
                    item
                    for item in understanding.information_requests
                    if getattr(item, "fact_name", None)
                ),
                None,
            )
            if request is not None:
                semantic_fact_name = request.fact_name
        evidence = self.product_fact_evidence.evaluate(
            message,
            before_turn,
            semantic_fact_name=semantic_fact_name,
        )
        if evidence is None:
            return base_candidate
        if (
            evidence.request.product_ref.kind == ProductReferenceKind.UNRESOLVED
            and current_actions.intersection({"select", "show"})
        ):
            # A generic selection request may be phrased as a question
            # ("какой котёл смотреть?").  It has no concrete product scope,
            # so the ProductFact boundary cannot own it.  Keep the native V2
            # selection candidate rather than replacing it with a misleading
            # request for SKU.  A truly unscoped product-fact question without
            # Selection still follows the existing safe ambiguity path.
            return base_candidate
        normalized_message = " ".join(message.casefold().replace("ё", "е").split())
        base_supported_direct_request = bool(
            current_actions.intersection(
                {"check_price", "check_stock", "get_link"}
            )
            or any(
                marker in normalized_message
                for marker in (
                    "сколько стоит",
                    "какая цена",
                    "какова цена",
                    "есть в наличии",
                    "ссылка на товар",
                    "дай ссылку",
                )
            )
        )
        if (
            evidence.request.predicate == "unsupported_product_fact"
            and bool(getattr(base_candidate, "eligible_for_delivery", False))
            and bool(getattr(base_candidate, "semantic_accepted", False))
            and base_supported_direct_request
        ):
            # The generic unknown-attribute guard exists to prevent an
            # unverified Legacy fallback in Preview.  It must not replace a
            # fully valid native V2 answer (for example an already supported
            # price question) merely because this bounded adapter does not own
            # that predicate.
            return base_candidate
        candidate = build_v2_product_fact_candidate(
            outcome,
            base_candidate,
            evidence,
            self.answer_source_snapshot_v2,
            session_id=session_id,
            turn_id=turn_id,
        )
        return candidate or base_candidate

    def _maybe_build_v2_comparison_candidate(
        self,
        message: str,
        before_turn: SessionState,
        outcome: DialogueV2Outcome,
        base_candidate: Any,
        *,
        session_id: str,
        turn_id: str,
    ) -> Any:
        """Give a typed Compare action the deterministic visible-card seam."""

        request = build_comparison_request(
            outcome,
            before_turn,
            original_utterance=message,
        )
        if request is None:
            return base_candidate
        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return base_candidate
        result = validate_comparison_result(
            request,
            build_comparison_result(
                request,
                snapshot,
                visible_cards=(
                    before_turn.v2_last_products
                    if before_turn.v2_last_products
                    else before_turn.last_products
                ),
            ),
            snapshot,
        )
        # Keep the typed request in the candidate even on rejection: Shadow
        # telemetry can then distinguish no scope, stale scope, and a gate
        # rejection without exposing a V2 response.
        candidate = build_v2_comparison_candidate(
            outcome,
            base_candidate,
            result,
            snapshot,
            session_id=session_id,
            turn_id=turn_id,
        )
        if candidate is not None:
            return candidate.model_copy(update={"comparison_request": request})
        return base_candidate.model_copy(
            update={
                "comparison_request": request,
                "comparison_result": result,
                "rejection_reason_codes": tuple(
                    dict.fromkeys(
                        (*base_candidate.rejection_reason_codes, *result.reason_codes)
                    )
                ),
            }
        )

    def _maybe_build_v2_compatibility_candidate(
        self,
        message: str,
        before_turn: SessionState,
        outcome: DialogueV2Outcome,
        base_candidate: Any,
        *,
        session_id: str,
        turn_id: str,
    ) -> Any:
        """Give Compatibility one source-bound, two-sided V2 seam.

        This adapter reads only the current V2 source snapshot.  For a missing
        thermostat interface it may use the already accepted ProductFact
        passport/embedding/verifier path; it never composes a Legacy answer or
        runs a broad catalogue search.
        """

        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return base_candidate
        request = build_compatibility_request(
            outcome,
            before_turn,
            snapshot,
            original_utterance=message,
        )
        if request is None:
            return base_candidate
        result = validate_compatibility_result(
            request,
            build_compatibility_result(
                request,
                snapshot,
                interface_facts=InterfaceFactService(
                    snapshot,
                    product_fact_evidence=self.product_fact_evidence,
                    products=self.search_agent.products,
                ),
            ),
            snapshot,
        )
        candidate = build_v2_compatibility_candidate(
            outcome,
            base_candidate,
            result,
            snapshot,
            session_id=session_id,
            turn_id=turn_id,
        )
        if candidate is not None:
            return candidate.model_copy(update={"compatibility_request": request})
        return base_candidate.model_copy(
            update={
                "compatibility_request": request,
                "compatibility_result": result,
                "rejection_reason_codes": tuple(
                    dict.fromkeys(
                        (*base_candidate.rejection_reason_codes, *result.reason_codes)
                    )
                ),
            }
        )

    def _maybe_build_v2_calculation_candidate(
        self,
        message: str,
        before_turn: SessionState,
        outcome: DialogueV2Outcome,
        base_candidate: Any,
        *,
        session_id: str,
        turn_id: str,
    ) -> Any:
        """Give CALCULATE a source-bound quantity × price seam.

        It intentionally does not call Legacy response composition or search
        the catalogue.  An explicit SKU is resolved by the existing strict
        resolver; otherwise only already delivered V2 cards are eligible.
        """

        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return base_candidate
        request = build_calculation_request(
            outcome,
            before_turn,
            snapshot,
            original_utterance=message,
        )
        if request is None:
            return base_candidate
        result = validate_calculation_result(
            request,
            build_calculation_result(request, snapshot),
            snapshot,
        )
        candidate = build_v2_calculation_candidate(
            outcome,
            base_candidate,
            result,
            snapshot,
            session_id=session_id,
            turn_id=turn_id,
        )
        if candidate is not None:
            return candidate.model_copy(update={"calculation_request": request})
        return base_candidate.model_copy(
            update={
                "calculation_request": request,
                "calculation_result": result,
                "rejection_reason_codes": tuple(
                    dict.fromkeys(
                        (*base_candidate.rejection_reason_codes, *result.reason_codes)
                    )
                ),
            }
        )

    def _maybe_build_v2_offer_fact_candidate(
        self,
        message: str,
        before_turn: SessionState,
        outcome: DialogueV2Outcome,
        base_candidate: Any,
        *,
        session_id: str,
        turn_id: str,
    ) -> Any:
        """Answer one price, stock or link fact from a checked visible offer.

        This is intentionally before Calculation.  A question without a
        quantity (``Сколько стоит второй?``) is a catalogue fact, while a
        quantity × price request remains owned by the existing calculator.
        """

        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return base_candidate
        # A rejected semantic turn is never repaired by guessing an offer
        # fact from its surface wording.  An accepted generic direct-answer
        # plan is different: it can be structurally deliverable while still
        # lacking the source-bound price/stock/link requested by the buyer.
        # A resolved OfferFactResult is the more specific evidence-backed
        # implementation of that action and must take precedence.
        if outcome.status != "applied":
            return base_candidate
        request = build_offer_fact_request(
            outcome,
            before_turn,
            snapshot,
            original_utterance=message,
        )
        if request is None:
            return base_candidate
        result = build_offer_fact_result(request, snapshot)
        native_candidate_is_complete = (
            bool(getattr(base_candidate, "semantic_accepted", False))
            and bool(getattr(base_candidate, "contracts_resolved", False))
            and bool(getattr(base_candidate, "eligible_for_delivery", False))
            and getattr(base_candidate, "response", None) is not None
        )
        # Do not let an unbound price word turn a complete selection or other
        # valid response into a clarification.  Once a product is resolved,
        # however, the grounded OfferFactResult is authoritative.
        if (
            native_candidate_is_complete
            and result.status != OfferFactStatus.ANSWERED
        ):
            return base_candidate
        candidate = build_v2_offer_fact_candidate(
            outcome,
            base_candidate,
            result,
            snapshot,
            session_id=session_id,
            turn_id=turn_id,
        )
        if candidate is not None:
            return candidate.model_copy(
                update={
                    "offer_fact_request": request,
                    "offer_fact_result": result,
                }
            )
        return base_candidate.model_copy(
            update={
                "offer_fact_request": request,
                "offer_fact_result": result,
                "rejection_reason_codes": tuple(
                    dict.fromkeys(
                        (*base_candidate.rejection_reason_codes, *result.reason_codes)
                    )
                ),
            }
        )

    def _stage6_runtime(
        self,
        before_turn: SessionState,
        qa_mode: DialogueQAMode | None = None,
    ) -> CutoverRuntime:
        qa_preview = bool(
            qa_mode == DialogueQAMode.V2_PREVIEW
            and self._qa_v2_resources_enabled()
        )
        qa_shadow = bool(
            qa_mode == DialogueQAMode.SHADOW
            and self._qa_v2_resources_enabled()
        )
        return CutoverRuntime(
            routing_enabled=(
                self.settings.dialogue_v2_routing_enabled
                or qa_preview
                or qa_shadow
            ),
            shadow_compare_enabled=(
                self.settings.dialogue_v2_shadow_compare_enabled or qa_shadow
            ),
            live_delivery_enabled=(
                self.settings.dialogue_v2_live_delivery_enabled or qa_preview
            ),
            internal_canary_enabled=(
                self.settings.dialogue_v2_internal_canary_enabled
            ),
            internal_canary_percent=(
                self.settings.dialogue_v2_internal_canary_percent
            ),
            local_preview_enabled=(
                self.settings.dialogue_v2_local_preview_enabled
            ),
            qa_preview_enabled=qa_preview,
            external_actions_enabled=(
                self.settings.commerce_external_execution_enabled
            ),
            force_legacy=self.settings.dialogue_v2_force_legacy,
            registry_valid=self.cutover_registry_v2.valid,
            is_existing_session=bool(
                before_turn.history
                or before_turn.live_dialogue_state_v2 is not None
                or before_turn.dialogue_state_v2 is not None
            ),
            sticky_cell_id=before_turn.v2_migration_cell_id,
            sticky_assignment_id=before_turn.v2_sticky_assignment_id,
        )

    def _public_product_kinds_v2(
        self,
        response: ChatResponse,
    ) -> dict[str, ProductKind]:
        result: dict[str, ProductKind] = {}
        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return result
        for product in response.products:
            source = snapshot.product(product.sku)
            if source is not None:
                result[product.sku] = source.product_kind
        return result

    def _session_for_v2_turn_product_context(
        self,
        before_turn: SessionState,
        state_after: DialogueStateV2,
    ) -> SessionState:
        """Build a read-only capability view for the active typed goal.

        The persisted session intentionally keeps one UI-facing current list
        for compatibility with Legacy.  V2 capabilities must not read that
        global list after a goal was reactivated: ``первый`` then has to mean
        the first card of the resumed goal, not the latest unrelated list.
        This method changes no stored state; the delivery commit remains the
        only writer of customer-visible cards and typed historical scopes.
        """

        snapshot = self.answer_source_snapshot_v2
        if snapshot is None:
            return before_turn
        context = turn_product_context(
            state_after,
            source_revision=snapshot.source_revision,
        )
        if context.is_valid:
            cards: list[ProductCard] = []
            for sku in context.scope.ordered_skus:
                source = self._find_product_by_sku(sku)
                snapshot_product = snapshot.product(sku)
                if (
                    source is None
                    or snapshot_product is None
                    or source.price is None
                    or not source.url
                ):
                    # A stale/missing historical scope is never replaced with
                    # the current global view.  The downstream capability will
                    # report its normal fail-closed scope boundary.
                    return before_turn.model_copy(
                        deep=True,
                        update={
                            "v2_last_products": [],
                            "last_products": [],
                            "v2_selection_id": None,
                            "v2_source_revision": None,
                            "product_focus": None,
                        },
                    )
                cards.append(
                    ProductCard(
                        sku=source.sku,
                        name=source.name,
                        brand=source.brand,
                        price=source.price,
                        currency=source.currency,
                        stock_status=source.stock_status,
                        stock_qty=source.stock_qty,
                        url=source.url,
                        image_url=source.image_url,
                        characteristics={},
                    )
                )
            focus_sku = context.scope.focus_sku
            focus_source = self._find_product_by_sku(focus_sku) if focus_sku else None
            return before_turn.model_copy(
                deep=True,
                update={
                    "v2_last_products": cards,
                    "last_products": cards,
                    "shown_product_skus": [card.sku for card in cards],
                    "shown_result_signature": context.scope.selection_id,
                    "v2_selection_id": context.scope.selection_id,
                    "v2_source_revision": context.scope.source_revision,
                    "product_focus": (
                        ProductFocusState(
                            sku=focus_sku,
                            category=focus_source.category_path or None,
                            origin="v2_reactivated_goal_scope",
                        )
                        if focus_sku is not None and focus_source is not None
                        else None
                    ),
                },
            )

        # Once a typed state has historical selections, a missing scope for
        # its active goal is meaningful (for example an old direct-fact-only
        # task).  Do not silently borrow the latest cards from another goal.
        if state_after.active_goal_id is not None and state_after.delivered_selection_scopes:
            return before_turn.model_copy(
                deep=True,
                update={
                    "v2_last_products": [],
                    "last_products": [],
                    "v2_selection_id": None,
                    "v2_source_revision": None,
                    "product_focus": None,
                },
            )
        # Older stored V2 sessions have no per-goal history yet.  They retain
        # the existing one-scope behavior until their next delivered Selection
        # creates a safe typed scope.
        return before_turn

    def _commit_v2_response(
        self,
        before_turn: SessionState,
        message: str,
        client_turn_id: str | None,
        turn_id: str,
        decision: Any,
        candidate: Any,
    ) -> tuple[ChatResponse, TurnCommit]:
        if candidate.response is None or candidate.response_digest is None:
            raise RuntimeError("cannot commit an incomplete V2 candidate")
        if self._response_digest(candidate.response) != candidate.response_digest:
            raise RuntimeError("v2_response_digest_mismatch_before_commit")
        snapshot = self.answer_source_snapshot_v2
        if (
            snapshot is None
            or candidate.catalog_revision != snapshot.source_revision
            or candidate.source_revision != snapshot.source_revision
        ):
            raise RuntimeError("stale_catalog_revision_before_v2_commit")
        selection_result = candidate.selection_result
        replaces_product_scope = (
            candidate.product_scope_effect
            == ProductScopeEffect.REPLACE_FROM_SELECTION
        )
        # Repeat the frozen-model invariant at the mutation boundary because
        # Pydantic ``model_copy(update=...)`` deliberately skips validation.
        if replaces_product_scope:
            if (
                selection_result is None
                or selection_result.status != SelectionResultStatus.SHOWN
                or not selection_result.outcome_gate_passed
            ):
                raise RuntimeError(
                    "v2_product_scope_replace_without_gated_selection"
                )
            if (
                tuple(item.sku for item in candidate.response.products)
                != selection_result.ordered_skus
            ):
                raise RuntimeError(
                    "v2_product_scope_replace_card_order_mismatch"
                )
        live_epoch_id = before_turn.v2_live_epoch_id or hashlib.sha256(
            f"{before_turn.session_id}:v2-live".encode("utf-8")
        ).hexdigest()[:24]
        delivery_id = hashlib.sha256(
            f"{turn_id}:{candidate.answer_plan_id}:{candidate.response_digest}".encode(
                "utf-8"
            )
        ).hexdigest()[:32]
        delivery = record_response_delivery(
            candidate.state_after,
            TurnMetadata(turn_id=turn_id),
            plan_id=str(candidate.answer_plan_id),
            response_digest=candidate.response_digest,
            delivery_id=delivery_id,
            live_epoch_id=live_epoch_id,
            selection_id=(
                selection_result.selection_id
                if replaces_product_scope and selection_result is not None
                else None
            ),
            catalog_revision=(
                selection_result.catalog_revision
                if replaces_product_scope and selection_result is not None
                else None
            ),
            selection_goal_id=(
                selection_result.goal_id
                if replaces_product_scope and selection_result is not None
                else None
            ),
            selection_task_id=(
                selection_result.task_id
                if replaces_product_scope and selection_result is not None
                else None
            ),
            selection_ordered_skus=(
                selection_result.ordered_skus
                if replaces_product_scope and selection_result is not None
                else ()
            ),
            selection_focus_sku=(
                selection_result.ordered_skus[0]
                if (
                    replaces_product_scope
                    and selection_result is not None
                    and len(selection_result.ordered_skus) == 1
                )
                else None
            ),
        )
        selected = before_turn.model_copy(deep=True)
        selected.live_dialogue_state_v2 = delivery.state
        selected.v2_live_epoch_id = live_epoch_id
        selected.v2_sticky_assignment_id = decision.sticky_assignment_id
        selected.v2_migration_cell_id = decision.cell_id
        selected.session_revision = before_turn.session_revision + 1
        cards: list[ProductCard] = []
        for public in candidate.response.products:
            snapshot_product = snapshot.product(public.sku)
            if snapshot_product is None or any(
                (
                    snapshot_product.name != public.name,
                    snapshot_product.price != public.price,
                    snapshot_product.currency != public.currency,
                    snapshot_product.stock_status != public.stock_status,
                    snapshot_product.url != public.url,
                    snapshot_product.image_url != public.image_url,
                )
            ):
                raise RuntimeError("stale_catalog_fact_before_v2_commit")
            source = self._find_product_by_sku(public.sku)
            if source is None or source.price is None or not source.url:
                raise RuntimeError("V2 response source changed before commit")
            cards.append(
                ProductCard(
                    sku=source.sku,
                    name=source.name,
                    brand=source.brand,
                    price=source.price,
                    currency=source.currency,
                    stock_status=source.stock_status,
                    stock_qty=source.stock_qty,
                    url=source.url,
                    image_url=source.image_url,
                    characteristics={},
                )
            )
        if replaces_product_scope:
            if selection_result is None:  # Defensive type narrowing.
                raise RuntimeError(
                    "v2_product_scope_replace_without_gated_selection"
                )
            selected.v2_last_products = cards
            # Only a delivered, source-checked Selection owns the ordered
            # customer-visible scope. Contextual cards in ProductFact (and any
            # future non-selection response) must not reach this branch.
            selected.last_products = cards
            selected.shown_product_skus = [card.sku for card in cards]
            selected.shown_result_signature = selection_result.selection_id
            if len(cards) == 1:
                selected.product_focus = ProductFocusState(
                    sku=cards[0].sku,
                    category=selection_result.category,
                    origin="v2_delivered_selection",
                )
            else:
                # A list supports ordinal references but has no single "этот".
                selected.product_focus = None
            selected.v2_selection_id = selection_result.selection_id
            selected.v2_source_revision = selection_result.catalog_revision
        else:
            # ``response.products`` describes only this HTTP response.  Keep
            # every field of an existing ordered Selection unchanged.  For a
            # standalone direct fact on a fresh session, retain a legacy
            # active-view card solely for old read paths; it is deliberately
            # not promoted to a versioned V2 Selection.
            if cards and not selected.last_products and not selected.v2_last_products:
                selected.last_products = cards
            focus_sku = candidate.focus_product_sku
            if focus_sku is not None:
                focus_source = self._find_product_by_sku(focus_sku)
                if (
                    snapshot.product(focus_sku) is None
                    or focus_source is None
                ):
                    raise RuntimeError("v2_product_focus_source_missing")
                selected.product_focus = ProductFocusState(
                    sku=focus_sku,
                    category=focus_source.category_path or None,
                    origin="v2_contextual_product",
                )
        self._append_history(selected, message, candidate.response.answer)
        self._record_idempotent_response(
            selected,
            client_turn_id,
            candidate.response,
        )
        selected_state_revision = hashlib.sha256(
            delivery.state.model_dump_json().encode("utf-8")
        ).hexdigest()
        commit = TurnCommit(
            commit_id=delivery_id,
            turn_id=turn_id,
            response_owner=ResponseOwner.V2,
            execution_mode=decision.execution_mode,
            session_revision_before=before_turn.session_revision,
            session_revision_after=selected.session_revision,
            response_digest=candidate.response_digest,
            selected_state_revision=selected_state_revision,
            answer_plan_id=candidate.answer_plan_id,
            catalog_revision=candidate.catalog_revision,
            live_epoch_id=live_epoch_id,
            external_command_ids=(),
            committed=True,
            reason_codes=(
                "v2_state_and_response_committed_atomically",
                f"product_scope_{candidate.product_scope_effect.value}",
            ),
        )
        self.sessions.save(selected)
        return candidate.response, commit

    def _cutover_trace_payload(
        self,
        *,
        early_control: EarlyControlResult,
        decision: Any | None = None,
        candidate: Any | None = None,
        arbitration: Any | None = None,
        commit: TurnCommit | None = None,
        parity: Any | None = None,
        error: str | None = None,
    ) -> dict[str, Any]:
        candidate_summary = None
        selection_delivery = None
        comparison_delivery = None
        calculation_delivery = None
        product_fact_delivery = None
        offer_fact_delivery = None
        compatibility_delivery = None
        if candidate is not None:
            candidate_summary = candidate.model_dump(
                mode="json",
                exclude={"response", "state_before", "state_after"},
            )
            if candidate.selection_result is not None:
                selection_delivery = candidate.selection_result.model_dump(
                    mode="json"
                )
                selection_delivery["customer_visible_state_updated"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.selection_result.status.value == "shown"
                    and candidate.product_scope_effect
                    == ProductScopeEffect.REPLACE_FROM_SELECTION
                )
            if candidate.comparison_result is not None:
                comparison_delivery = candidate.comparison_result.model_dump(
                    mode="json"
                )
                comparison_delivery["customer_visible_scope_preserved"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.product_scope_effect
                    == ProductScopeEffect.PRESERVE
                )
            if candidate.calculation_result is not None:
                calculation_delivery = candidate.calculation_result.model_dump(
                    mode="json"
                )
                calculation_delivery["customer_visible_scope_preserved"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.product_scope_effect
                    == ProductScopeEffect.PRESERVE
                )
            if candidate.product_fact_delivery is not None:
                product_fact_delivery = candidate.product_fact_delivery.model_dump(
                    mode="json"
                )
                product_fact_delivery["customer_visible_scope_preserved"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.product_scope_effect
                    == ProductScopeEffect.PRESERVE
                )
            if candidate.offer_fact_result is not None:
                offer_fact_delivery = candidate.offer_fact_result.model_dump(
                    mode="json"
                )
                offer_fact_delivery["customer_visible_scope_preserved"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.product_scope_effect
                    == ProductScopeEffect.PRESERVE
                )
            if candidate.compatibility_result is not None:
                compatibility_delivery = candidate.compatibility_result.model_dump(
                    mode="json"
                )
                compatibility_delivery["customer_visible_scope_preserved"] = bool(
                    commit is not None
                    and commit.committed
                    and candidate.product_scope_effect
                    == ProductScopeEffect.PRESERVE
                )
        return {
            "schema_version": "1.0",
            "rollout_registry": {
                "revision": self.cutover_registry_v2.revision,
                "valid": self.cutover_registry_v2.valid,
                "source": self.cutover_registry_v2.source,
            },
            "runtime_controls": {
                "routing_enabled": self.settings.dialogue_v2_routing_enabled,
                "shadow_compare_enabled": (
                    self.settings.dialogue_v2_shadow_compare_enabled
                ),
                "live_delivery_enabled": (
                    self.settings.dialogue_v2_live_delivery_enabled
                ),
                "internal_canary_enabled": (
                    self.settings.dialogue_v2_internal_canary_enabled
                ),
                "internal_canary_percent": (
                    self.settings.dialogue_v2_internal_canary_percent
                ),
                "local_preview_enabled": (
                    self.settings.dialogue_v2_local_preview_enabled
                ),
                "force_legacy": self.settings.dialogue_v2_force_legacy,
                "external_execution_enabled": (
                    self.settings.commerce_external_execution_enabled
                ),
            },
            "early_control": early_control,
            "decision": decision,
            "candidate": candidate_summary,
            "selection_delivery": selection_delivery,
            "comparison_delivery": comparison_delivery,
            "calculation_delivery": calculation_delivery,
            "product_fact_delivery": product_fact_delivery,
            "offer_fact_delivery": offer_fact_delivery,
            "compatibility_delivery": compatibility_delivery,
            "arbitration": arbitration,
            "commit": commit,
            "parity": parity,
            "fallback_attempted": bool(
                arbitration is not None and arbitration.fallback_required
            ),
            "external_fallback_forbidden": bool(
                arbitration is not None
                and arbitration.external_fallback_forbidden
            ),
            "error": error,
        }

    def handle_chat(
        self,
        session_id: str,
        message: str,
        client_turn_id: str | None = None,
        qa_mode: DialogueQAMode | None = None,
    ) -> ChatResponse:
        # Turns inside one dialogue are transactional, while independent users
        # may proceed in parallel.  This preserves session history without the
        # latency penalty of a process-wide chat lock.
        with self._session_lock(session_id):
            # Third-party/test stores created before the shared-store contract
            # may not implement distributed locking.  Keep them compatible;
            # the process-local lock above still serializes their turns.
            turn_lock = getattr(self.sessions, "turn_lock", None)
            shared_lock = turn_lock(session_id) if callable(turn_lock) else nullcontext()
            with shared_lock:
                # Capture state while holding the distributed lock so a failed
                # turn cannot overwrite a successful concurrent worker turn.
                before_turn = self.sessions.snapshot(session_id)
                cached = self._idempotent_response(before_turn, client_turn_id)
                if cached is not None:
                    return cached
                trace = None
                if (
                    self.settings.diagnostic_telemetry_enabled
                    or self.settings.semantic_shadow_enabled
                    or self.settings.dialogue_state_v2_shadow_enabled
                    or self.settings.seller_policy_v2_shadow_enabled
                    or self._stage3_shadow_enabled()
                    or self._stage4_shadow_enabled()
                    or self._stage5_shadow_enabled()
                    or self._stage6_pipeline_enabled()
                    or self.settings.dialogue_v2_force_legacy
                    or qa_mode is not None
                ):
                    try:
                        trace = build_turn_trace(
                            self.settings,
                            session_id=session_id,
                            message=message,
                            state_before=before_turn,
                            catalog=self.search_agent.get_catalog_manifest(
                                self.products_loaded_from
                            ),
                            qa_mode=(qa_mode.value if qa_mode is not None else None),
                        )
                    except Exception as trace_exc:
                        logger.warning(
                            "Could not start diagnostic trace error_type=%s",
                            type(trace_exc).__name__,
                        )
                        trace = None
                request_budget = getattr(self.llm_client, "request_budget", None)
                budget_scope = request_budget() if callable(request_budget) else nullcontext()
                with activate_turn_trace(trace):
                    try:
                        early_control = EarlyControlResult()
                        semantic = None
                        live_v2_outcome = None
                        live_candidate = None
                        live_decision = None
                        live_arbitration = None
                        live_commit = None
                        cutover_error = None
                        with budget_scope:
                            self._request_agents.composer = ResponseComposerAgent(self.llm_client)
                            self._request_agents.consultant = ConsultantAgent(
                                self.llm_client,
                                model=self.settings.llm_model_strong,
                            )
                            if self._stage6_live_attempt_enabled(qa_mode):
                                early_control = self._stage6_early_control(
                                    message,
                                    before_turn,
                                )
                                if early_control.outcome == EarlyControlOutcome.PASS:
                                    try:
                                        if not self.catalog_snapshot_v2:
                                            self._ensure_products_loaded()
                                        semantic = self.semantic_interpreter.interpret(
                                            message,
                                            before_turn,
                                        )
                                        record_semantic_shadow(semantic)
                                        turn_id = (
                                            client_turn_id
                                            or (trace.trace_id if trace is not None else None)
                                            or hashlib.sha256(
                                                (
                                                    f"{session_id}:"
                                                    f"{before_turn.session_revision}:"
                                                    f"{len(before_turn.history)}"
                                                ).encode("utf-8")
                                            ).hexdigest()
                                        )
                                        live_v2_outcome = self._run_stage6_v2_candidate(
                                            before_turn.live_dialogue_state_v2
                                            or before_turn.dialogue_state_v2
                                            or DialogueStateV2(),
                                            semantic,
                                            turn_id,
                                            before_turn,
                                        )
                                        capability_session = (
                                            self._session_for_v2_turn_product_context(
                                                before_turn,
                                                live_v2_outcome.state_after,
                                            )
                                        )
                                        live_candidate = build_v2_turn_candidate(
                                            live_v2_outcome,
                                            self.answer_source_snapshot_v2,
                                            session_id=session_id,
                                            turn_id=turn_id,
                                            original_utterance=message,
                                            previously_delivered_products=tuple(
                                                capability_session.last_products
                                            ),
                                            current_product_focus=(
                                                capability_session.product_focus.sku
                                                if capability_session.product_focus is not None
                                                else None
                                            ),
                                        )
                                        live_candidate = (
                                            self._maybe_build_v2_comparison_candidate(
                                                message,
                                                capability_session,
                                                live_v2_outcome,
                                                live_candidate,
                                                session_id=session_id,
                                                turn_id=turn_id,
                                            )
                                        )
                                        live_candidate = (
                                            self._maybe_build_v2_compatibility_candidate(
                                                message,
                                                capability_session,
                                                live_v2_outcome,
                                                live_candidate,
                                                session_id=session_id,
                                                turn_id=turn_id,
                                            )
                                        )
                                        live_candidate = (
                                            self._maybe_build_v2_product_fact_candidate(
                                                message,
                                                capability_session,
                                                semantic,
                                                live_v2_outcome,
                                                live_candidate,
                                                session_id=session_id,
                                                turn_id=turn_id,
                                            )
                                        )
                                        live_candidate = (
                                            self._maybe_build_v2_offer_fact_candidate(
                                                message,
                                                capability_session,
                                                live_v2_outcome,
                                                live_candidate,
                                                session_id=session_id,
                                                turn_id=turn_id,
                                            )
                                        )
                                        live_candidate = (
                                            self._maybe_build_v2_calculation_candidate(
                                                message,
                                                capability_session,
                                                live_v2_outcome,
                                                live_candidate,
                                                session_id=session_id,
                                                turn_id=turn_id,
                                            )
                                        )
                                        # Record every live-attempt outcome,
                                        # including candidates rejected before
                                        # arbitration.  Otherwise the release
                                        # trace would show only the compact
                                        # rejection summary and lose the exact
                                        # failing Stage 2–5 boundary.
                                        record_dialogue_v2_shadow(live_v2_outcome)
                                        session_fingerprint = hashlib.sha256(
                                            session_id.encode("utf-8")
                                        ).hexdigest()
                                        live_decision = decide_cutover(
                                            early_control,
                                            live_candidate,
                                            self.cutover_registry_v2.registry(),
                                            self._stage6_runtime(before_turn, qa_mode),
                                            session_fingerprint=session_fingerprint,
                                        )
                                        live_arbitration = arbitrate_turn(
                                            live_decision,
                                            live_candidate,
                                        )
                                        if live_arbitration.response_owner == ResponseOwner.V2:
                                            response, live_commit = self._commit_v2_response(
                                                before_turn,
                                                message,
                                                client_turn_id,
                                                turn_id,
                                                live_decision,
                                                live_candidate,
                                            )
                                            record_cutover_v2(
                                                self._cutover_trace_payload(
                                                    early_control=early_control,
                                                    decision=live_decision,
                                                    candidate=live_candidate,
                                                    arbitration=live_arbitration,
                                                    commit=live_commit,
                                                )
                                            )
                                            finish_turn_trace(
                                                trace,
                                                response=response,
                                                state_after=self.sessions.snapshot(session_id),
                                            )
                                            return response
                                    except Exception as live_exc:
                                        # No external commands are enabled for the
                                        # internal canary. Restore the untouched
                                        # snapshot and let legacy own the whole turn.
                                        self.sessions.restore(before_turn)
                                        # Exception text from a provider or a
                                        # store can contain credential-bearing
                                        # URLs.  The trace keeps a stable
                                        # layer/code without persisting the
                                        # provider exception text.
                                        cutover_error = (
                                            f"{type(live_exc).__name__}:"
                                            "stage6_candidate_or_commit_failed"
                                        )
                                else:
                                    session_fingerprint = hashlib.sha256(
                                        session_id.encode("utf-8")
                                    ).hexdigest()
                                    live_decision = decide_cutover(
                                        early_control,
                                        None,
                                        self.cutover_registry_v2.registry(),
                                        self._stage6_runtime(before_turn, qa_mode),
                                        session_fingerprint=session_fingerprint,
                                    )
                            response = self._handle_chat(session_id, message)

                        # Run only after the legacy response is fully produced.
                        # The result is never copied to intent, session, search
                        # or response and its failures are contained internally.
                        qa_shadow_enabled = bool(
                            qa_mode == DialogueQAMode.SHADOW
                            and self._qa_v2_resources_enabled()
                        )
                        v2_shadow_enabled = bool(
                            qa_mode != DialogueQAMode.LEGACY
                            and (
                                self.settings.dialogue_state_v2_shadow_enabled
                                or self.settings.seller_policy_v2_shadow_enabled
                                or self._stage3_shadow_enabled()
                                or self._stage4_shadow_enabled()
                                or self._stage5_shadow_enabled()
                                or qa_shadow_enabled
                                or (
                                    self.settings.dialogue_v2_routing_enabled
                                    and self.settings.dialogue_v2_shadow_compare_enabled
                                )
                            )
                        )
                        # A valid V2 reduction is still useful migration state
                        # when legacy owned the public response (for example a
                        # text description immediately after the verified photo
                        # capability boundary).  Keep it only in the separate
                        # shadow field: it cannot alter legacy slots, cards or
                        # the answer that was just produced.  A later eligible
                        # canary turn may then continue the typed goal instead
                        # of silently forgetting accepted customer facts.
                        #
                        # The ordinary shadow pipeline below remains the owner
                        # when it is enabled, and any live-path exception stays
                        # fail-closed without a partial state write.
                        if (
                            not v2_shadow_enabled
                            and live_commit is None
                            and cutover_error is None
                            and live_v2_outcome is not None
                            and live_v2_outcome.status == "applied"
                        ):
                            state_with_v2 = self.sessions.snapshot(session_id)
                            state_with_v2.dialogue_state_v2 = (
                                live_v2_outcome.state_after
                            )
                            self.sessions.save(state_with_v2)
                        if (
                            semantic is None
                            and qa_mode != DialogueQAMode.LEGACY
                            and (
                                self.settings.semantic_shadow_enabled
                                or v2_shadow_enabled
                            )
                            and not (
                                self._stage6_pipeline_enabled()
                                and early_control.outcome
                                in {
                                    EarlyControlOutcome.SAFETY_RESPONSE,
                                    EarlyControlOutcome.EMERGENCY_RESPONSE,
                                    EarlyControlOutcome.BLOCKED,
                                }
                            )
                        ):
                            semantic = self.semantic_interpreter.interpret(
                                message,
                                before_turn,
                            )
                            record_semantic_shadow(semantic)

                        if v2_shadow_enabled and semantic is not None:
                            v2_before = (
                                before_turn.dialogue_state_v2
                                or DialogueStateV2()
                            )
                            try:
                                turn_id = (
                                    trace.trace_id
                                    if trace is not None
                                    else hashlib.sha256(
                                        (
                                            f"{session_id}:{len(before_turn.history)}:"
                                            f"{message}"
                                        ).encode("utf-8")
                                    ).hexdigest()
                                )
                                v2_outcome = self.dialogue_controller_v2.run(
                                    v2_before,
                                    semantic,
                                    TurnMetadata(turn_id=turn_id),
                                    policy_enabled=(
                                        self.settings.seller_policy_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    product_contracts_enabled=(
                                        self._stage3_shadow_enabled()
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    catalog_planner_enabled=(
                                        self.settings.catalog_planner_v2_shadow_enabled
                                        or self.settings.solution_plan_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    solution_plan_enabled=(
                                        self.settings.solution_plan_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    catalog_snapshot=self.catalog_snapshot_v2,
                                    commerce_workflows_enabled=(
                                        self.settings.commerce_workflows_v2_shadow_enabled
                                        or qa_shadow_enabled
                                    ),
                                    handoff_workflow_enabled=(
                                        self.settings.handoff_workflow_v2_shadow_enabled
                                    ),
                                    commerce_outbox_enabled=(
                                        self.settings.commerce_outbox_v2_shadow_enabled
                                    ),
                                    commerce_context=build_commerce_context_snapshot(
                                        self.sessions.snapshot(session_id),
                                        get_business_facts(),
                                    ),
                                    commerce_capabilities=self.commerce_capabilities_v2,
                                    answer_plan_enabled=(
                                        self.settings.answer_plan_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    response_renderer_enabled=(
                                        self.settings.response_renderer_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    response_grounding_enabled=(
                                        self.settings.response_grounding_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    progress_guard_enabled=(
                                        self.settings.progress_guard_v2_shadow_enabled
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    ),
                                    answer_source_snapshot=(
                                        self.answer_source_snapshot_v2
                                    ),
                                )
                                if (
                                    v2_outcome.status == "applied"
                                    and (
                                        self.settings.dialogue_state_v2_shadow_enabled
                                        or self._stage3_shadow_enabled()
                                        or self._stage4_shadow_enabled()
                                        or self._stage5_shadow_enabled()
                                        or self.settings.dialogue_v2_shadow_compare_enabled
                                        or qa_shadow_enabled
                                    )
                                ):
                                    state_with_v2 = self.sessions.snapshot(session_id)
                                    state_with_v2.dialogue_state_v2 = (
                                        v2_outcome.state_after
                                    )
                                    self.sessions.save(state_with_v2)
                                record_dialogue_v2_shadow(v2_outcome)
                                if (
                                    self.settings.dialogue_v2_shadow_compare_enabled
                                    or qa_shadow_enabled
                                ):
                                    shadow_candidate = build_v2_turn_candidate(
                                        v2_outcome,
                                        self.answer_source_snapshot_v2,
                                        session_id=session_id,
                                        turn_id=turn_id,
                                        original_utterance=message,
                                        previously_delivered_products=tuple(
                                            before_turn.last_products
                                        ),
                                        current_product_focus=(
                                            before_turn.product_focus.sku
                                            if before_turn.product_focus is not None
                                            else None
                                        ),
                                    )
                                    shadow_candidate = (
                                        self._maybe_build_v2_comparison_candidate(
                                            message,
                                            before_turn,
                                            v2_outcome,
                                            shadow_candidate,
                                            session_id=session_id,
                                            turn_id=turn_id,
                                        )
                                    )
                                    shadow_candidate = (
                                        self._maybe_build_v2_compatibility_candidate(
                                            message,
                                            before_turn,
                                            v2_outcome,
                                            shadow_candidate,
                                            session_id=session_id,
                                            turn_id=turn_id,
                                        )
                                    )
                                    shadow_candidate = (
                                        self._maybe_build_v2_product_fact_candidate(
                                            message,
                                            before_turn,
                                            semantic,
                                            v2_outcome,
                                            shadow_candidate,
                                            session_id=session_id,
                                            turn_id=turn_id,
                                        )
                                    )
                                    shadow_candidate = (
                                        self._maybe_build_v2_calculation_candidate(
                                            message,
                                            before_turn,
                                            v2_outcome,
                                            shadow_candidate,
                                            session_id=session_id,
                                            turn_id=turn_id,
                                        )
                                    )
                                    parity = assess_response_parity(
                                        response,
                                        shadow_candidate,
                                        self.sessions.snapshot(session_id),
                                        self._public_product_kinds_v2(response),
                                    )
                                    shadow_decision = decide_cutover(
                                        early_control,
                                        shadow_candidate,
                                        self.cutover_registry_v2.registry(),
                                        self._stage6_runtime(
                                            before_turn,
                                            qa_mode,
                                        ).model_copy(
                                            update={
                                                "live_delivery_enabled": False,
                                                "internal_canary_enabled": False,
                                                "qa_preview_enabled": False,
                                            }
                                        ),
                                        session_fingerprint=hashlib.sha256(
                                            session_id.encode("utf-8")
                                        ).hexdigest(),
                                    )
                                    record_cutover_v2(
                                        self._cutover_trace_payload(
                                            early_control=early_control,
                                            decision=shadow_decision,
                                            candidate=shadow_candidate,
                                            parity=parity,
                                        )
                                    )
                            except Exception as shadow_exc:
                                # Stage 2 is observational.  A reducer, policy,
                                # telemetry or persistence failure must not
                                # roll back the already successful legacy turn.
                                record_dialogue_v2_shadow(
                                    DialogueV2Outcome(
                                        status="failed",
                                        state_before=v2_before,
                                        state_after=v2_before,
                                        error=(
                                            f"{type(shadow_exc).__name__}: "
                                            f"{shadow_exc}"
                                        )[:1200],
                                    )
                                )

                        if live_candidate is not None and not self.settings.dialogue_v2_shadow_compare_enabled:
                            parity = assess_response_parity(
                                response,
                                live_candidate,
                                self.sessions.snapshot(session_id),
                                self._public_product_kinds_v2(response),
                            )
                            record_cutover_v2(
                                self._cutover_trace_payload(
                                    early_control=early_control,
                                    decision=live_decision,
                                    candidate=live_candidate,
                                    arbitration=live_arbitration,
                                    parity=parity,
                                    error=cutover_error,
                                )
                            )
                        elif live_candidate is None and live_decision is not None:
                            record_cutover_v2(
                                self._cutover_trace_payload(
                                    early_control=early_control,
                                    decision=live_decision,
                                    error=cutover_error,
                                )
                            )
                        elif cutover_error is not None:
                            record_cutover_v2(
                                self._cutover_trace_payload(
                                    early_control=early_control,
                                    error=cutover_error,
                                )
                            )

                        if (
                            client_turn_id
                            or self._stage6_pipeline_enabled()
                            or qa_mode is not None
                        ):
                            committed_legacy = self.sessions.snapshot(session_id)
                            committed_legacy.session_revision += 1
                            self._record_idempotent_response(
                                committed_legacy,
                                client_turn_id,
                                response,
                            )
                            self.sessions.save(committed_legacy)

                        finish_turn_trace(
                            trace,
                            response=response,
                            state_after=self.sessions.snapshot(session_id),
                        )
                        return response
                    except Exception as exc:
                        self.sessions.restore(before_turn)
                        finish_turn_trace(
                            trace,
                            response=None,
                            state_after=self.sessions.snapshot(session_id),
                            error=exc,
                        )
                        raise

    def _session_lock(self, session_id: str) -> RLock:
        with self._session_locks_guard:
            return self._session_locks.setdefault(session_id, RLock())

    def _maybe_problem_frame_response(
        self,
        session_id: str,
        message: str,
        intent: IntentResult,
        session: SessionState,
        agents_used: list[str],
    ) -> ChatResponse | None:
        """Start from an everyday problem before asking for a product code."""

        text = normalize_text(message)
        active = str(session.slots.get("_problem_frame") or "")
        code = str((intent.raw or {}).get("problem_frame") or "")

        # Problem-framing replies can return before the ordinary slot merge.
        # Preserve measurements that were explicitly stated on that same turn;
        # otherwise a phrase such as ``тёплый пол 85 м²`` is acknowledged but
        # the next question asks for the area again.
        if (active == "floor_comfort" or code == "floor_comfort") and {
            "warm_floor_area_m2",
            "area_m2",
            "warm_floor_type",
        }.intersection(intent.slots):
            frame_slots = {
                key: value
                for key, value in intent.slots.items()
                if key
                in {
                    "warm_floor_area_m2",
                    "area_m2",
                    "warm_floor_type",
                    "has_warm_floor",
                    "project_scope",
                }
            }
            if "area_m2" in frame_slots and "warm_floor_area_m2" not in frame_slots:
                frame_slots["warm_floor_area_m2"] = frame_slots.pop("area_m2")
            self._merge_persistent_slots(
                session,
                frame_slots,
                explicit_slots=frame_slots,
            )

        # A diagnostic frame is subordinate to an explicitly named product.
        # For example, a pump serving radiators and underfloor heating is still
        # a pump-selection dialogue; the word ``тёплый пол`` describes the
        # circuit and must not replace the customer's confirmed goal.
        if (
            (active == "floor_comfort" or code == "floor_comfort")
            and intent.category == "pumps"
            and (
                session.category == "pumps"
                or re.search(r"\b(?:насос|помп)\w*\b", text)
                or any(
                    key in intent.slots
                    for key in (
                        "head_m",
                        "required_flow_m3_h",
                        "mounting_length_mm",
                        "connection_size",
                    )
                )
            )
        ):
            session.slots.pop("_problem_frame", None)
            session.slots.pop("_problem_frame_stage", None)
            return None

        # A problem frame owns discovery, not the entire future catalogue
        # conversation.  Once the customer positively chooses a technology,
        # retire the diagnostic frame so later stock/price questions reach the
        # cards instead of being mistaken for another request about analysis.
        if active == "water_quality" and re.search(
            r"\b(?:посмотр\w*|покаж\w*|выбира\w*|беру|нужн\w*|хочу)\b"
            r"[^.?!]{0,70}\b(?:систем\w*\s+)?(?:обратн\w*\s+осмос\w*|"
            r"фильтр\w*|умягчител\w*)\b",
            text,
        ):
            session.slots.pop("_problem_frame", None)
            session.slots.pop("_problem_frame_stage", None)
            active = ""
            if code == "water_quality":
                code = ""
        if not code and active and continues_problem_frame(active, message):
            code = active
        if not code:
            return None

        acknowledges_action = bool(
            "?" not in message
            and re.search(
                r"\b(?:начну|проверю|попробую|сделаю|уточню|узнаю|"
                r"напишу|спрошу|обращусь|позвоню|схожу|подумаю|рассмотрю|"
                r"надо\s+проверить|нужно\s+проверить|так\s+и\s+сделаю)\b",
                text,
            )
        )

        if active == code == "weak_pressure":
            if any(marker in text for marker in ["центральн", "водопровод"]):
                answer = (
                    "Раз на верхнем этаже слабо во всех точках, а местные сетки и краны "
                    "проверены, следующий шаг — замерить давление манометром на вводе и "
                    "по возможности на верхнем этаже при закрытых кранах и при открытом "
                    "разборе. Такой замер может сделать сантехник; одновременно запросите "
                    "у управляющей/водоснабжающей организации норматив и фактическое "
                    "давление на вводе. Повысительный насос рассматривают только если "
                    "вводное давление подтверждено и его установка допустима: иначе он "
                    "может маскировать проблему стояка или нарушать работу сети."
                )
            else:
                answer = (
                    "Для колодца или скважины сначала проверяют не новый насос, а штатную "
                    "индикацию давления, фильтр, настройки реле и меняется ли давление при "
                    "разборе. Запишите показания манометра при закрытых кранах и во время "
                    "душа; если манометра нет, это безопасно измерит специалист. По этим "
                    "двум значениям и данным существующего насоса станет понятно, нужна "
                    "настройка, устранение засора или замена оборудования."
                )
            session.pending_question = None
            session.pending_category = None
            session.pending_slot_keys = []
            session.clear_pending_question_state()
            agents_used.extend(["ProblemFramingAgent", "GuardrailsAgent"])
            self._append_history(session, message, answer)
            return self._response(
                session_id, answer, [], False, intent, session, agents_used
            )

        if active == code == "boiler_failure" and any(
            marker in text
            for marker in ["почему", "провер", "молчит", "не запуска", "слома", "ремонт"]
        ):
            answer = (
                "До покупки замены старый котёл разумно проверить, но без вскрытия газовой "
                "части. Безопасно запишите: есть ли питание и что показывает штатный дисплей/"
                "код ошибки; есть ли запрос от термостата; какое давление видно на штатном "
                "манометре и что по этому коду/давлению говорит паспорт именно вашей модели. "
                "Не снимайте крышку, не перемыкайте датчики и не пытайтесь поджигать горелку. "
                "Если пахнет газом — не включайте электроприборы, перекройте газ только если "
                "это безопасно, выйдите и звоните 104/112. Если запаха нет, запишите модель, "
                "индикацию и эти наблюдения. К сожалению, этот чат пока не принимает "
                "фотографии; при необходимости передайте снимок авторизованному сервису: он определит, "
                "ремонтировать котёл или уже подбирать замену."
            )
            session.pending_question = None
            session.pending_category = None
            session.pending_slot_keys = []
            session.clear_pending_question_state()
            agents_used.extend(["ProblemFramingAgent", "GuardrailsAgent"])
            self._append_history(session, message, answer)
            return self._response(
                session_id, answer, [], False, intent, session, agents_used
            )

        if active == code == "hot_water_shortage":
            explicitly_chose_type = bool(
                re.search(
                    r"\b(?:беру|выбираю|нужен|нужна|хочу)\b[^.?!]{0,24}"
                    r"\b(?:накопительн\w*|проточн\w*|косвенн\w*)\b",
                    text,
                )
            )
            if explicitly_chose_type:
                session.slots.pop("_problem_frame", None)
                session.slots.pop("_problem_frame_stage", None)
                return None
            stage = int(session.slots.get("_problem_frame_stage") or 1) + 1
            session.slots["_problem_frame_stage"] = stage
            existing_tank = any(
                marker in text
                for marker in ["бойлер", "бак", "накопительн", "стоит в подвал"]
            )
            asks_where_to_find = bool(
                any(
                    marker in text
                    for marker in ["где", "посмотр", "шильдик", "табличк", "не знаю", "не чита"]
                )
                and any(marker in text for marker in ["литр", "объём", "объем", "мощност", "модель"])
            )
            asks_flow_check = any(
                marker in text
                for marker in ["поток", "перекры", "слабо теч", "напор", "клапан"]
            )
            has_tank_measurements = bool(
                re.search(r"\b\d+(?:[,.]\d+)?\s*л(?:итр\w*)?\b", text)
                and re.search(r"\b\d+(?:[,.]\d+)?\s*квт\b", text)
            )
            if asks_flow_check:
                answer = (
                    "Проверять нужно в контексте ГВС, а не дренажа. Сравните напор холодной "
                    "и горячей воды на одном и том же кране и повторите на второй точке. "
                    "Снаружи можно лишь убедиться, что доступные штатные запорные краны на "
                    "входе/выходе полностью открыты по инструкции; фильтр, обратный клапан, "
                    "смесительный клапан и внутреннюю обвязку пусть проверяет сервисный "
                    "специалист после безопасного отключения. Ничего не разбирайте под "
                    "давлением и не трогайте газовую/электрическую часть. Сообщите сервису, "
                    "на всех ли кранах слабее именно горячая вода и падает ли только "
                    "температура или также расход."
                )
            elif has_tank_measurements:
                answer = (
                    "Данные 200 л, 3 кВт и 60 °C уже полезны. Полный бак такого объёма не "
                    "может заново нагреться за столь короткий наблюдаемый промежуток, поэтому "
                    "скорее требует проверки того, что именно меняется: температура или "
                    "сам расход, на одной точке или на всех, только при одновременном разборе "
                    "или после исчерпания запаса. Запишите эти четыре наблюдения. Сервису "
                    "также нужно проверить датчик/нагрев, смесительный клапан и подключение; "
                    "по одному литражу покупать новый бак пока рано."
                )
            elif asks_where_to_find:
                answer = (
                    "Объём, мощность и модель ищите на заводской табличке снаружи корпуса "
                    "или в паспорте — часто она сбоку, сзади либо возле нижней части и "
                    "подводок. Электрическую крышку снимать не нужно. К сожалению, этот чат "
                    "пока не принимает фотографии, поэтому перепишите модель и значения "
                    "с таблички и словами опишите подключённые трубы. Для электрического бака "
                    "важны объём в литрах и мощность в кВт; у бойлера косвенного нагрева "
                    "электрической мощности может не быть — тогда нужны модель, объём и "
                    "данные котла. Номинал автомата в щитке не заменяет мощность прибора."
                )
            elif stage == 2 and existing_tank:
                answer = (
                    "Раз горячая вода уже идёт из существующего бака, сначала не выбирайте "
                    "новый тип прибора. Нужно понять, заканчивается запас или бак перестал "
                    "нормально нагреваться: найдите на наружной табличке модель, объём в "
                    "литрах и, если он электрический, мощность в кВт; запишите установленную "
                    "температуру и примерное время восстановления после душа. Корпус и "
                    "электрическую часть не вскрывайте. По этим данным можно отличить "
                    "недостаточный объём/долгий нагрев от неисправности или смешивания воды."
                )
            elif stage == 2 and "центральн" in text:
                answer = (
                    "Если нестабильна именно центральная горячая вода, сначала стоит "
                    "проверить, одинаково ли это на всех кранах, и зафиксировать время/"
                    "температуру для управляющей организации: водонагреватель не устраняет "
                    "причину в общедомовой системе, а работает как отдельный резерв. Для "
                    "двух человек и одновременного душа с краном резерв подбирают после "
                    "проверки доступной электрической мощности и места установки. "
                    + WATER_HEATER_TYPES_CONSULT
                )
            else:
                answer = (
                    WATER_HEATER_TYPES_CONSULT
                    if stage == 2
                    else "Для следующего шага не нужно угадывать новый литраж: сначала "
                    "перепишите модель и значения с заводской таблички существующего прибора. "
                    "К сожалению, этот чат пока не принимает фотографии. "
                    "Если табличка не читается, сервисный специалист определит тип и "
                    "проверит нагрев без вскрытия пользователем."
                )
            session.pending_question = None
            session.pending_category = None
            session.pending_slot_keys = []
            session.clear_pending_question_state()
            agents_used.append("ProblemFramingAgent")
            self._append_history(session, message, answer)
            return self._response(
                session_id, answer, [], False, intent, session, agents_used
            )

        if active == code == "sewer_odor":
            stage = int(session.slots.get("_problem_frame_stage") or 1) + 1
            session.slots["_problem_frame_stage"] = stage
            if acknowledges_action:
                answer = (
                    "Да, это правильный безопасный порядок. Важное уточнение: если запах "
                    "исчезнет именно после долива воды, наиболее вероятно пересыхание "
                    "гидрозатвора, а не автоматически неисправность вентиляции. Если он "
                    "быстро вернётся, появится бульканье или долив не поможет, передайте "
                    "сантехнику результат проверки — тогда он проверит соединения и "
                    "вентиляцию стояка. Покупать деталь заранее не нужно."
                )
                session.slots.pop("_problem_frame", None)
                session.slots.pop("_problem_frame_stage", None)
            else:
                answer = (
                    "Проверьте источники по одному. Сначала проветрите ванную, долейте "
                    "воду в слив ванны, душевой трап и раковину. Затем по очереди временно "
                    "накрывайте отверстие каждого слива влажной плёнкой или мокрой тканью "
                    "и отмечайте, при каком закрытом сливе запах пропадает; ничего не "
                    "заливайте лаком или герметиком. В унитазе гидрозатвор — это видимая "
                    "вода в чаше. Если локализовать источник не получается, запах быстро "
                    "возвращается или есть бульканье, сантехнику нужно проверить сифонные "
                    "соединения и вентиляцию стояка. Покупка унитаза или трубы без этой "
                    "проверки проблему не решит."
                )
            session.last_products = []
            session.pending_question = None
            session.pending_category = None
            session.pending_slot_keys = []
            session.clear_pending_question_state()
            agents_used.extend(["ProblemFramingAgent", "GuardrailsAgent"])
            self._append_history(session, message, answer)
            return self._response(
                session_id, answer, [], False, intent, session, agents_used
            )

        if active == code == "floor_comfort":
            known_area_m2 = self._latest_household_area_m2(message, session)
            mentions_electric = any(
                marker in text for marker in ["электр", "мат", "кабель"]
            )
            if mentions_electric:
                session.slots["_problem_frame_solution"] = "electric"
            electric_context = bool(
                mentions_electric
                or session.slots.get("_problem_frame_solution") == "electric"
            )
            asks_to_contact_building_authority = bool(
                not acknowledges_action
                and any(marker in text for marker in ["управляющ", "ук", "тсж"])
                and any(
                    marker in text
                    for marker in ["напис", "спрос", "уточн", "обрат", "позвон"]
                )
            )
            asks_existing_building_docs = bool(
                any(
                    marker in text
                    for marker in [
                        "техпаспорт",
                        "техническ паспорт",
                        "план дома",
                        "планах дома",
                        "схем дома",
                    ]
                )
                and any(
                    marker in text
                    for marker in ["посмотр", "указан", "есть ли", "где", "информац"]
                )
            )
            asks_permission_process = bool(
                not acknowledges_action
                and any(
                    marker in text
                    for marker in [
                        "разреш",
                        "согласов",
                        "документ",
                        "служб",
                        "управляющ",
                        "тсж",
                        "проектиров",
                    ]
                )
                and any(
                    marker in text
                    for marker in [
                        "как провер",
                        "как узнать",
                        "как уточн",
                        "какие",
                        "какой",
                        "через",
                        "запрос",
                        "обращ",
                        "без обращ",
                    ]
                )
            )
            if asks_to_contact_building_authority:
                answer = (
                    "Да, это правильный первый шаг и врезаться в стояк для него не нужно. "
                    "Направьте в управляющую организацию письменный запрос: допустим ли "
                    "водяной тёплый пол в вашей квартире при существующей схеме центрального "
                    "отопления, какие исходные данные и проект требуются, кто вправе выполнить "
                    "расчёт и согласование. Приложите план квартиры и описание предполагаемой "
                    "зоны, но не покупайте трубы и не начинайте монтаж до письменного ответа. "
                    "Если подключение к общедомовой системе не допускается, отдельно считайте "
                    "электрический вариант по свободной площади, покрытию и доступной мощности."
                )
                session.pending_question = None
                session.pending_category = None
                session.pending_slot_keys = []
                session.clear_pending_question_state()
                agents_used.extend(["ProblemFramingAgent", "GuardrailsAgent"])
                self._append_history(session, message, answer)
                return self._response(
                    session_id, answer, [], False, intent, session, agents_used
                )
            if asks_existing_building_docs:
                document_explanations = int(
                    session.slots.get("_floor_building_docs_explanations") or 0
                )
                if document_explanations:
                    answer = (
                        "В техпаспорте квартиры или поэтажном плане можно найти геометрию и "
                        "иногда расположение инженерных элементов, но обычно это не документ "
                        "с ответом «водяной пол разрешён». Нужна актуальная схема отопления "
                        "дома и письменное решение управляющей организации о допустимости "
                        "изменения, технических условиях и проекте. Поэтому планы можно "
                        "приложить к запросу, но использовать их вместо согласования нельзя."
                    )
                else:
                    answer = (
                        "Посмотреть можно, но техпаспорт квартиры или план дома сам по себе "
                        "обычно не является разрешением на изменение отопления. В нём может "
                        "быть планировка и часть сведений об инженерной системе; актуальная "
                        "схема стояков, допустимые изменения и требования к проекту находятся "
                        "в технической документации дома у управляющей организации/ТСЖ. "
                        "Попросите их письменно проверить вашу идею по этой документации и "
                        "назвать необходимые технические условия. Отсутствие запрета на "
                        "доступном плане не означает разрешение на врезку."
                    )
                session.slots["_floor_building_docs_explanations"] = (
                    document_explanations + 1
                )
                session.pending_question = None
                session.pending_category = None
                session.pending_slot_keys = []
                session.clear_pending_question_state()
